svg.script:
(function () {
  const svg = document.documentElement;
  const tip = document.getElementById('tip');
  const bg = document.getElementById('tipbg');
  const text = document.getElementById('tiptext');

  function show(el) {
    const raw = el.getAttribute('data-tip') || '';
    const lines = raw.split('|||');
    while (text.firstChild) text.removeChild(text.firstChild);

    lines.forEach((line, i) => {
      const t = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      t.setAttribute('x', '12');
      t.setAttribute('dy', i === 0 ? '0' : '18');
      t.textContent = line;
      text.appendChild(t);
    });

    const box = el.getBBox();
    const x = box.x + box.width + 12;
    const y = box.y - 10;
    const h = 18 * lines.length + 18;
    const w = 335;
    bg.setAttribute('width', w);
    bg.setAttribute('height', h);

    let tx = x;
    let ty = y;
    if (tx + w > 1230) tx = box.x - w - 12;
    if (ty + h > 770) ty = 770 - h;
    if (ty < 8) ty = 8;

    tip.setAttribute('transform', `translate(${tx},${ty})`);
    tip.setAttribute('visibility', 'visible');
  }

  function hide() {
    tip.setAttribute('visibility', 'hidden');
  }

  svg.querySelectorAll('circle[data-tip]').forEach(el => {
    el.addEventListener('mouseenter', () => show(el));
    el.addEventListener('mouseleave', hide);
    el.addEventListener('focus', () => show(el));
    el.addEventListener('blur', hide);
  });
})();
